using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MerfitCustomerApi.Domain.Entities;

namespace MerfitCustomerApi.Infrastructure.Configurations;

/// <summary>
/// UserRefreshToken varliginin veritabani (Entity Framework Core) yapilandirmasini tanimlar.
/// </summary>
public class UserRefreshTokenConfiguration : IEntityTypeConfiguration<UserRefreshToken>
{
    /// <summary>
    /// UserRefreshToken varligi icin tablo adi, birincil anahtar, alan kisitlari ve iliskileri yapilandirir.
    /// </summary>
    public void Configure(EntityTypeBuilder<UserRefreshToken> builder)
    {
        // Tablo adini belirtir.
        builder.ToTable("UserRefreshToken", "authentication");

        // Birincil anahtari tanimlar.
        builder.HasKey(x => x.Id);

        // Yenileme jetonunun degeri.
        builder.Property(x => x.Token)
