            .HasMaxLength(500);

        // Jetonun olusturuldugu IP adresi.
        builder.Property(x => x.CreatedByIp)
            .IsRequired(false)
            .HasMaxLength(300);

        // Jetonun iptal edildigi IP adresi.
        builder.Property(x => x.RevokedByIp)
            .IsRequired(false)
            .HasMaxLength(300);

        // Bu jetonun yerine gecen yeni jeton degeri.
        builder.Property(x => x.ReplacementToken)
            .IsRequired(false)
            .HasMaxLength(500);

        // Iliskiler (foreign key) yapilandirmasi.
        // Jetonun ait oldugu kullanicinin kimligi.
        builder.HasOne<ApplicationUser>()
